L["Slowly orbits your action bar buttons around each bar's centre while Party Mode is active. The buttons stay upright, so clicking, cooldowns and keybinds are unaffected. Pauses in combat, where moving a button is blocked."] = "Orbita lentamente os botões da sua barra de ação ao redor do centro de cada barra enquanto o Modo de Festa está ativo. Os botões permanecem na posição correta, então cliques, recargas e atalhos não são afetados. Pausa em combate, onde mover um botão é bloqueado."
