-- == Unlock / Edit Mode =====================================================
L["%s matched to %s. Unmatch in Unlock Mode to edit."] = "%s correspondido a %s. Desfaça a correspondência no Modo de Desbloqueio para editar."
L["%s matched to %s. Unmatch to edit."] = "%s correspondido a %s. Desfaça a correspondência para editar."
L["All Elements"] = "Todos os elementos"
L["Anchor to %1$s"] = "Ancorar a %1$s"
L["Center on Screen"] = "Centralizar na tela"
L["Click any element\nto anchor to it"] = "Clique em um elemento\npara ancorar nele"
L["Click any element\nto match its height"] = "Clique em um elemento\npara igualar sua altura"
L["Click any element\nto match its width"] = "Clique em um elemento\npara igualar sua largura"
L["Exit"] = "Sair"
