L["Grid Lines\nDimmed"] = "Linhas Guia\nEscuras"
L["Grid Lines\nDisabled"] = "Linhas Guia\nDesativado"
L["Grow Centered Horizontal"] = "Crescer centralizado na horizontal"
L["Grow Centered Vertical"] = "Crescer centralizado na vertical"
L["Exit Without Saving"] = "Sair sem salvar"
L["Movable left-aligned distance text for your current target (default 30-35, optional 30+ / 30), colored by yard distance. Off by default; position or Anchor to a unit frame in Unlock Mode."] = "Texto de distância móvel alinhado à esquerda para seu alvo atual (padrão 30-35, opcional 30+ / 30), colorido pela distância em jardas. Desativado por padrão; posicione ou ancore a um quadro de unidade no Modo de Desbloqueio."
L["Other"] = "Outros"
L["Position/size data cannot be synced across profiles due to Unlock Mode systems like anchoring, width/height matching and growth direction. This addon's sync is purely for settings that do not impact position, sizing or anchors."] = "Dados de posição/tamanho não podem ser sincronizados entre perfis devido a sistemas do Modo de Desbloqueio como ancoragem, correspondência de largura/altura e direção de crescimento. A sincronização deste addon é apenas para configurações que não afetam posição, tamanho ou âncoras."
L["Select Element"] = "Selecionar elemento"
L["Select which specs you want %s to be assigned to"] = "Selecione a quais especializações deseja atribuir %s"
L["Shows a large on-screen alert (e.g. \"Player DIED!\") whenever a party or raid member dies, so you immediately notice deaths during dungeons and raids. Use Unlock Mode to reposition the alert."] = "Mostra um grande alerta na tela (ex.: \"Player DIED!\") sempre que um membro do grupo ou raide morre, para que você perceba as mortes imediatamente durante masmorras e raides. Use o Modo de Desbloqueio para reposicionar o alerta."
L["Shows a large on-screen text when you enter and/or leave combat (e.g. \"+Combat\" / \"-Combat\"). Use the cog to set the display text, size, colors and which transitions are shown; use Unlock Mode to reposition the alert."] = "Mostra um texto grande na tela quando você entra e/ou sai de combate (ex.: \"+Combat\" / \"-Combat\"). Use o ícone de engrenagem para definir o texto exibido, tamanho, cores e quais transições são mostradas; use o Modo de Desbloqueio para reposicionar o alerta."
L["This element doesn't support both Height and Width matching"] = "Este elemento não é compatível com a correspondência de altura e largura ao mesmo tempo"
L["This feature requires Snap Elements to be enabled"] = "Este recurso requer que o Encaixe esteja ativado"
L["Unsaved Changes"] = "Alterações não salvas"
L["You have unsaved position changes.\nWhat would you like to do?"] = "Você tem alterações de posição não salvas.\nO que deseja fazer?"
L["|cff%sEUI|r |cffffffffUnlock Mode|r"] = "|cff%sEUI|r |cffffffffModo de Desbloqueio|r"

