L["Max Nest Span"] = "Amplitude máxima de aninhamento"
L["The widest angle a nest's entries may spread over. They stay on one ring for as long as they fit inside it; the rest go onto a second ring further out."] = "O ângulo mais amplo que as entradas de um aninhamento podem ocupar. Elas permanecem em um anel enquanto couberem nele; o restante vai para um segundo anel mais externo."
