L["Dim Unusable Entries"] = "Escurecer entradas inutilizáveis"
L["Tint an entry that would do nothing right now: red when the target is out of range, blue when you are short of the resource, and gray when the game refuses it for any other reason. Spells and items only -- the game reports every toy as unusable, and a macro's usability depends on what its body resolves to."] = "Tinge uma entrada que não faria nada agora: vermelho quando o alvo está fora de alcance, azul quando falta recurso, e cinza quando o jogo a recusa por qualquer outro motivo. Apenas feitiços e itens -- o jogo reporta todo brinquedo como inutilizável, e a usabilidade de uma macro depende do que seu corpo resolve."
L["Selection Color"] = "Cor de seleção"
L["Show Action Text Label"] = "Mostrar rótulo de texto da ação"
