L["Custom Color"] = "Cor personalizada"
L["Accent Color"] = "Cor de destaque"
L["Hide Unusable Entries"] = "Ocultar entradas inutilizáveis"
L["Hide entries this character cannot use: another class's specializations and spells, and macros this character does not have. One shared menu then fits every character. The menu editor always shows every entry."] = "Oculta entradas que este personagem não pode usar: especializações e feitiços de outra classe, e macros que este personagem não possui. Assim, um único menu compartilhado serve para todos os personagens. O editor de menu sempre mostra todas as entradas."
L["Toggle World Markers"] = "Alternar marcadores de mundo"
L["Use a world marker entry again to pick that marker back up. Off places the marker again, at the new position.\nThis does not change the entry that clears all world markers, or the cycling entry."] = "Usar uma entrada de marcador de mundo novamente pega aquele marcador de volta. Desativado o coloca novamente, na nova posição.\nIsso não altera a entrada que limpa todos os marcadores de mundo, nem a entrada de ciclagem."
