L["When using custom raid sizes, don't count members in hidden groups toward the raid-size breakpoint. For example, if you hide groups 7 and 8, a full 40-man raid is sized as if it were 24-man instead of jumping to the 30-man frame size. Has no effect unless you have custom raid sizes set up."] = "Ao usar tamanhos de raide personalizados, não conta membros em grupos ocultos para o ponto de corte do tamanho da raide. Por exemplo, se você ocultar os grupos 7 e 8, uma raide completa de 40 jogadores é dimensionada como se fosse de 24 jogadores, em vez de saltar para o tamanho de quadro de 30 jogadores. Não tem efeito a menos que você tenha tamanhos de raide personalizados configurados."
