L["Delete Override Group"] = "Excluir Grupo de Substituição"
L["Delete Spec Group"] = "Excluir Grupo de Especialização"
L["Delete the custom Buff Manager for '%s'? Its conditions return to your default Buff Manager."] = "Excluir o Gerenciador de Buffs personalizado de '%s'? As condições dele voltam para o seu Gerenciador de Buffs padrão."
L["Delete the custom Buff Manager for '%s'? Its specs return to your default Buff Manager."] = "Excluir o Gerenciador de Buffs personalizado de '%s'? As especializações dele voltam para o seu Gerenciador de Buffs padrão."
L["Delete the custom unlock mode for '%s'? Its conditions return to your default unlock mode layout."] = "Excluir o Modo de Desbloqueio personalizado de '%s'? As condições dele voltam para o layout padrão do seu Modo de Desbloqueio."
L["Delete the group '%s'? Its captured overrides are removed with it; settings keep their current live values."] = "Excluir o grupo '%s'? As substituições capturadas nele são removidas junto; as configurações mantêm seus valores atuais."
L["Edit Group: %s"] = "Editar Grupo: %s"
L["Edit normally: changes apply to your current spec"] = "Editar normalmente: as alterações se aplicam à sua especialização atual"
L["Edit Override Group"] = "Editar Grupo de Substituição"
L["Editing as %s"] = "Editando como %s"
L["EllesmereUI Profile switched. Reload UI to apply?"] = "Perfil do EllesmereUI trocado. Recarregar interface para aplicar?"
L["EUI Architect"] = "EUI Architect"
L["held by '%s'"] = "mantido por '%s'"
L["Import"] = "Importar"
L["New Overrides System"] = "Novo Sistema de Substituições"
L["New Spec Group"] = "Novo Grupo de Especialização"
L["No conditional overrides yet. Click the Conditional Overrides button next to the module search bar and create a conditional group (Dungeon, Raid, Keybind...). Spec overrides always take precedence over conditionals."] = "Ainda não há substituições condicionais. Clique no botão Substituições Condicionais ao lado da barra de busca de módulos e crie um grupo condicional (Masmorra, Raide, Atalho...). Substituições de especialização sempre têm prioridade sobre condicionais."
L["no key set"] = "nenhuma tecla definida"
L["No spec overrides yet. Click the spec glyph next to the module search bar, select or create a spec group, and any setting you change while editing as that group is saved here."] = "Ainda não há substituições de especialização. Clique no ícone de especialização ao lado da barra de busca de módulos, selecione ou crie um grupo de especialização; qualquer configuração alterada enquanto estiver editando como esse grupo é salva aqui."
L["Override Active: %s"] = "Substituição Ativa: %s"
L["Overrides are locked: this page's custom Buff Manager is active. Leave the Buff Manager tab to manage overrides."] = "As substituições estão bloqueadas: o Gerenciador de Buffs personalizado desta página está ativo. Saia da aba do Gerenciador de Buffs para gerenciar as substituições."
L["Paste an EllesmereUI profile string below"] = "Cole abaixo uma string de perfil do EllesmereUI"
L["Performance"] = "Desempenho"
L["Promote & Reload"] = "Promover e Recarregar"
L["Promote Override & Delete ALL Overrides"] = "Promover Substituição e Excluir TODAS as Substituições"
L["Promote Override to Profile"] = "Promover Substituição para Perfil"
L["Promoting an override reloads the UI and cannot run in combat. Leave combat and try again."] = "Promover uma substituição recarrega a interface e não pode ser feito em combate. Saia do combate e tente novamente."
L["Reload Recommended"] = "Recarregamento Recomendado"
L["Remove Override"] = "Remover Substituição"
L["Remove Stranded Override"] = "Remover Substituição Isolada"
L["Remove the stranded '%s' override for %s? The spec returns to the shared default."] = "Remover a substituição isolada '%s' de %s? A especialização volta ao padrão compartilhado."
L["Rescue tool for a profile built inside an override: the selected group's settings and layouts become this profile's own baseline, then ALL spec override groups are deleted. Conditional overrides are not affected."] = "Ferramenta de resgate para um perfil construído dentro de uma substituição: as configurações e layouts do grupo selecionado se tornam a base deste perfil, e então TODOS os grupos de substituição de especialização são excluídos. Substituições condicionais não são afetadas."
L["Showing the '%s' override's value. Edit it from that override's editing mode."] = "Mostrando o valor da substituição '%s'. Edite-o a partir do modo de edição dessa substituição."
L["Spec Overrides"] = "Substituições de Espec."
L["Stranded Overrides"] = "Substituições Isoladas"
L["Switch to a spec in this group to customize its Unlock Mode"] = "Mude para uma especialização deste grupo para personalizar o Modo de Desbloqueio dela"
L["The damage and tank cut of Light of Nitex. The same style refocused on your rotation, procs, and cooldowns front and center."] = "A versão de dano e tank de Light of Nitex. O mesmo estilo, reorientado para destacar sua rotação, procs e recargas."
L["The damage dealer cut of Midnight Lily. A focused, low-clutter layout that keeps your rotation and cooldowns front and center."] = "A versão de causador de dano de Midnight Lily. Um layout focado e com pouca poluição visual, que mantém sua rotação e recargas em destaque."
L["The dark counterpart to Lazar's Dawn. A moody, high-contrast layout that keeps focus locked on the fight."] = "A contraparte sombria de Lazar's Dawn. Um layout de alto contraste e atmosfera intensa, que mantém o foco travado na luta."
L["The signature EllesmereUI layout exactly as designed. Vibrant class colors, clear cd tracking, and every module working in harmony."] = "O layout característico do EllesmereUI, exatamente como projetado. Cores de classe vibrantes, rastreamento de cd claro e todos os módulos funcionando em harmonia."
L["Ungrouped"] = "Desagrupado"
L["You changed settings while profile sync is active. Please reload your UI for sync changes to take effect."] = "Você alterou configurações enquanto a sincronização de perfil estava ativa. Recarregue sua interface para que as alterações de sincronização tenham efeito."
L["Your current spec has its own custom Buff Manager, so conditional Buff Managers never apply to it."] = "Sua especialização atual tem seu próprio Gerenciador de Buffs personalizado, então Gerenciadores de Buffs condicionais nunca se aplicam a ela."
L["Your current spec has its own custom unlock mode, so conditional unlock modes never apply to it. Swap to a spec without one to customize this."] = "Sua especialização atual tem seu próprio Modo de Desbloqueio personalizado, então Modos de Desbloqueio condicionais nunca se aplicam a ela. Mude para uma especialização sem um para personalizar isso."

