L["Blizzard Atlas Texture"] = "Textura Atlas da Blizzard"
L["Blizzard's bar artwork is never recolored, so fill color modes and threshold colors will not tint the bar while this is enabled. To keep threshold colors visible, use Recolor Text Instead."] = "A arte de barra da Blizzard nunca é recolorida, então os modos de cor de preenchimento e as cores de limite não tingem a barra enquanto isso estiver ativado. Para manter as cores de limite visíveis, use Recolorir Texto em Vez Disso."
L["Border on individual pips"] = "Borda em segmentos individuais"
L["Caster"] = "Conjurador"
L["Cat"] = "Felino"
L["Changes the cast bar color based on the current empower stage. Colors transition from red (stage 1) through yellow to green (max stage)."] = "Altera a cor da barra de lançamento com base no estágio de Potencialização atual. As cores fazem a transição do vermelho (estágio 1), passando por amarelo, até verde (estágio máximo)."
L["Channel Ticks"] = "Pulsos de Canalização"
L["Charged Color"] = "Cor Carregada"
L["Choose the color of recharging runes instead of a dimmed version of the rune color."] = "Escolha a cor das runas em recarga, em vez de uma versão escurecida da cor da runa."
L["Class Resource Bar"] = "Barra de Recurso de Classe"
