L["Colored Empowered Stages"] = "Estágios Potencializados Coloridos"
L["Creates a class resource bar for Ignore Pain tracking. To see stack text, you must have Ignore Pain tracked in your Blizzard CDM \"Tracked Buffs\" or \"Tracked Bars\" section."] = "Cria uma barra de recurso de classe para rastrear Ignorar Dor. Para ver o texto de pilhas, você precisa ter Ignorar Dor rastreado na seção \"Buffs Rastreados\" ou \"Barras Rastreadas\" do CDM da Blizzard."
L["Custom class resource, health, and mana bar display."] = "Exibição personalizada de barras de recurso de classe, vida e mana."
L["Custom Recharge Color"] = "Cor de Recarga Personalizada"
L["Dark Mode Class Resource"] = "Recurso de Classe em Modo Escuro"
