L["Instance Only"] = "Apenas em Instâncias"
L["Keep the cast bar visible (sitting empty) when you are not casting, instead of hiding it."] = "Mantém a barra de lançamento visível (vazia) quando você não está lançando, em vez de ocultá-la."
L["Keep the GCD bar visible (sitting empty) when no global cooldown is running, instead of hiding it."] = "Mantém a barra de GCD visível (vazia) quando nenhuma recarga global está em andamento, em vez de ocultá-la."
L["Last Tick"] = "Último Pulso"
L["LATENCY"] = "LATÊNCIA"
L["Latency Overlay"] = "Sobreposição de Latência"
L["Makes partially filled Soul Shards and Essence darker than completed ones."] = "Deixa Fragmentos de Alma e Essência parcialmente preenchidos mais escuros que os completos."
L["Only available with the 'From' direction -- it highlights the pips at/above the threshold."] = "Disponível apenas com a direção 'De' -- destaca os segmentos no limite ou acima dele."
L["Only color at/above threshold"] = "Colorir Apenas no Limite ou Acima"
L["Only if Power Bar Hidden"] = "Somente se a Barra de Poder Estiver Oculta"
L["Only Instant Casts"] = "Apenas Lançamentos Instantâneos"
L["Only show the GCD bar for instant-cast abilities. While hard-casting or channeling a spell, the bar stays hidden (the cast bar already shows that progress)."] = "Mostra a barra de GCD apenas para habilidades de lançamento instantâneo. Durante um lançamento longo ou canalização, a barra permanece oculta (a barra de lançamento já mostra esse progresso)."
L["Only show the GCD bar while in a dungeon, raid, arena or battleground."] = "Mostra a barra de GCD apenas dentro de masmorras, raides, arenas ou campos de batalha."
L["Opacity of the bar fill; below 100 the world shows through the fill instead of the background."] = "Opacidade do preenchimento da barra; abaixo de 100 o mundo aparece através do preenchimento em vez do fundo."
L["Opacity of the resource fill; below 100 the world shows through the fill instead of the background."] = "Opacidade do preenchimento do recurso; abaixo de 100 o mundo aparece através do preenchimento em vez do fundo."
L["Out of Combat Opacity"] = "Opacidade Fora de Combate"
L["Pip Border"] = "Borda dos Segmentos"
L["Player Cast Bar"] = "Barra de Lançamento do Jogador"
L["Position by percent"] = "Posicionar por Porcentagem"
L["POSITIONING"] = "POSICIONAMENTO"
L["Power Background"] = "Fundo do Poder"
L["Power Bar Threshold"] = "Limite da Barra de Poder"
