L["Disabled runs no nameplate range checks. Auto uses your class and specialization's normal attack range. Custom uses the range set in the cog beside this option."] = "Desativado não executa verificações de alcance de placa de nome. Automático usa o alcance de ataque normal da sua classe e especialização. Personalizado usa o alcance definido na engrenagem ao lado desta opção."
L["Dispel Glow Style"] = "Estilo do Brilho de Dissipação"
L["Display the word \"FOCUS\" below caster/miniboss mobs in M+ if you have not set your focus. This is the same setting as in the FocusKick bar options. Disabled for specs with no kick."] = "Exibe a palavra \"FOCO\" abaixo de mobs conjuradores/minichefes no M+ caso você não tenha definido seu foco. É a mesma configuração das opções da barra FocusKick. Desativado para especializações sem interrupção."
