L["Hide enemy nameplates while you are out of combat; they return the moment combat starts. Drives the same game setting as the Show Enemy Name Plates keybind."] = "Oculta as placas de nome de inimigos enquanto você está fora de combate; elas voltam assim que o combate começa. Controla a mesma configuração do jogo que o atalho Placas de Nome de Inimigos."
L["Hide friendly player health bars and instead only see their names.\n\nRequires 'Simplified Friendly Nameplates' to be disabled in Blizzard's Nameplate settings (Esc > Options > Nameplates)."] = "Oculta as barras de vida de jogadores amigos e mostra apenas seus nomes.\n\nRequer que 'Placas de Nome Amigáveis Simplificadas' esteja desativado nas configurações de Placa de Nome da Blizzard (Esc > Opções > Placas de Nome)."
