L["Make friendly player and NPC nameplates click-through so their names never block your mouse or cause accidental friendly targeting.\n\nUse this when friendly names get in the way of clicking the world or the enemy nameplates behind them."] = "Torna as placas de nome de jogadores e NPCs amigos transparentes a cliques, para que seus nomes nunca bloqueiem o mouse ou causem alvo amigável acidental.\n\nUse isto quando nomes amigáveis atrapalharem cliques no mundo ou nas placas de nome de inimigos atrás deles."
