L["On quest mobs in the open world, replaces the quest icon with the objective progress (ex: kill quests show 0/6, percentage objectives show 50%)."] = "Em mobs de missão no mundo aberto, substitui o ícone de missão pelo progresso do objetivo (ex.: missões de matar mostram 0/6, objetivos percentuais mostram 50%)."
L["Opacity used for enemy nameplates outside the selected attack range."] = "Opacidade usada para placas de nome de inimigos fora do alcance de ataque selecionado."
L["OTHER COLORS"] = "OUTRAS CORES"
