L["This will display the word \"FOCUS\" below caster/miniboss mobs in M+ if you have not set your focus. Disabled for specs with no kick."] = "Isso exibirá a palavra \"FOCO\" abaixo de mobs conjuradores/minichefes no M+ caso você não tenha definido seu foco. Desativado para especializações sem interrupção."
