L["Show aura tooltips when hovering buff and debuff icons on all unit frames except boss frames."] = "Mostra dicas de aura ao passar o mouse sobre ícones de buffs e debuffs em todos os quadros de unidade, exceto quadros de chefe."
L["Show aura tooltips when hovering buff and debuff icons on boss frames."] = "Mostra dicas de aura ao passar o mouse sobre ícones de buffs e debuffs em quadros de chefe."
