L["Show dispel overlay preview"] = "Mostrar pré-visualização da sobreposição de dissipação"
L["Show Duration (Inside Cog)"] = "Mostrar Duração (Dentro da Engrenagem)"
L["Show every buff that has a duration (hides permanent buffs). While this is on, checked filters below are hidden instead of added."] = "Mostra todo buff que tem duração (oculta buffs permanentes). Enquanto isso estiver ativado, os filtros marcados abaixo ficam ocultos em vez de adicionados."
L["Show every buff. While this is on, checked filters below are hidden from the frame instead of added."] = "Mostra todo buff. Enquanto isso estiver ativado, os filtros marcados abaixo ficam ocultos do quadro em vez de adicionados."
L["Show every debuff. While this is on, checked filters below are hidden from the frame instead of added."] = "Mostra todo debuff. Enquanto isso estiver ativado, os filtros marcados abaixo ficam ocultos do quadro em vez de adicionados."
L["Show heal absorb preview"] = "Mostrar pré-visualização da absorção de cura"
L["Show Highlight Border"] = "Mostrar Borda de Destaque"
L["Show Icon on Right"] = "Mostrar Ícone à Direita"
L["Show in Instances"] = "Mostrar em Instâncias"
L["Show Kick Ready Mid-Cast Bar"] = "Mostrar Barra de Interrupção Pronta Durante o Lançamento"
L["Show Kick Ready Mid-Cast Tick"] = "Mostrar Marca de Interrupção Pronta Durante o Lançamento"
L["Show Nicknames"] = "Mostrar Apelidos"
L["Show on Boss Frames"] = "Mostrar nos Quadros de Chefe"
L["Show one decimal place on health text: health values like 240.5k and health percent like 77.3%. Power text is unaffected. Off by default."] = "Mostra uma casa decimal no texto de vida: valores de vida como 240.5k e porcentagem de vida como 77.3%. O texto de poder não é afetado. Desativado por padrão."
L["Show player nicknames from supported addons instead of character names on your main frames."] = "Mostra apelidos de jogadores de addons suportados em vez dos nomes de personagem nos seus quadros principais."
L["Show Portrait"] = "Mostrar Retrato"
L["Show Raid Marker"] = "Mostrar Marcador de Raide"
L["Shows any debuff with a dispel type (Magic, Curse, Disease, Poison, Bleed), even if you cannot remove it"] = "Mostra qualquer debuff com um tipo de dissipação (Magia, Maldição, Doença, Veneno, Sangramento), mesmo que você não possa removê-lo"
L["Shows a small white tick mark on the cast bar at the point where the cast will be when your interrupt comes off cooldown."] = "Mostra uma pequena marca branca na barra de lançamento no ponto em que o lançamento estará quando sua interrupção sair da recarga."
L["Shows a small white tick mark where the cast will be when your interrupt comes off cooldown."] = "Mostra uma pequena marca branca no ponto em que o lançamento estará quando sua interrupção sair da recarga."
L["Shows only auras with a dispel type you can dispel"] = "Mostra apenas auras com um tipo de dissipação que você pode dissipar"
L["Shows only buffs that can be canceled"] = "Mostra apenas buffs que podem ser cancelados"
L["Shows only buffs you can spellsteal or purge"] = "Mostra apenas buffs que você pode roubar ou remover"
L["Shows only crowd-control auras"] = "Mostra apenas auras de controle de grupo"
L["Shows only debuffs applied by bosses"] = "Mostra apenas debuffs aplicados por chefes"
L["Shows only debuffs Blizzard flags as important"] = "Mostra apenas debuffs marcados pela Blizzard como importantes"
L["Shows only debuffs flagged for your role"] = "Mostra apenas debuffs marcados para sua função"
L["Shows only debuffs from Blizzard's curated raid-frame debuff set"] = "Mostra apenas debuffs do conjunto selecionado pela Blizzard para quadros de raide"
L["Shows only debuffs not caused by any player or player pet (this is what shows most pve debuffs, do not check this while All Debuffs is selected!"] = "Mostra apenas debuffs não causados por nenhum jogador ou ajudante de jogador (isso é o que mostra a maioria dos debuffs de JxA; não marque isso enquanto Todos os Debuffs estiver selecionado!"
L["Shows only external defensive cooldowns cast on the unit"] = "Mostra apenas recargas de defensivas externas lançadas na unidade"
L["Shows only major defensive cooldowns"] = "Mostra apenas recargas de defensivas importantes"
L["Shows only the stricter in-combat subset of the raid set"] = "Mostra apenas o subconjunto mais restrito em combate do conjunto de raide"
L["Shows the nameplate-style dragon badge on elite, rare elite, and rare targets."] = "Mostra o emblema de dragão estilo placa de nome em alvos de elite, elite raro e raro."
L["Shows the overlay only for debuffs you can currently dispel."] = "Mostra a sobreposição apenas para debuffs que você pode dissipar no momento."
L["Shows the raid target marker icon on boss frames."] = "Mostra o ícone de marcador de alvo de raide nos quadros de chefe."
L["Show the main frames' hover highlight border on this frame. Turn off so this frame never recolors on mouseover. No effect when Highlight is off in the main frames' Hover Borders."] = "Mostra a borda de destaque ao passar o mouse dos quadros principais neste quadro. Desative para que este quadro nunca mude de cor ao passar o mouse. Sem efeito quando o Destaque está desativado nas Bordas ao Passar o Mouse dos quadros principais."
L["Show the name of who the boss is casting on."] = "Mostra o nome de quem o chefe está lançando."
L["Show the pet frame whenever you have a pet, ignoring the Player frame's visibility settings."] = "Mostra o quadro do ajudante sempre que você tiver um ajudante, ignorando as configurações de visibilidade do quadro do Jogador."
L["Show the unit's tooltip when hovering the frame itself."] = "Mostra a dica da unidade ao passar o mouse sobre o próprio quadro."
L["Show Tooltip For"] = "Mostrar Dica Para"
L["Simple Buff Display"] = "Exibição Simples de Buffs"
L["Simple Buff Position"] = "Posição Simples de Buffs"
L["Simple Debuff Display"] = "Exibição Simples de Debuffs"
L["Simple Debuff Position"] = "Posição Simples de Debuffs"
