L["The Combat Indicator is not available for the Focus frame."] = "O Indicador de Combate não está disponível para o quadro de Foco."
L["This frame's source changes require a UI reload to take effect."] = "Alterações na fonte deste quadro requerem recarregar a interface para ter efeito."
L["This option is only available for formats that display a percentage."] = "Esta opção está disponível apenas para formatos que exibem uma porcentagem."
