-- == Quality of Life ==========================================================
-- Module identity / general
L["Quality of life features and custom cursor."] = "Recursos de qualidade de vida e cursor personalizado."
L["Suppress Lua Errors"] = "Suprimir Erros de Lua"
L["Hides the Lua error popup. The same setting as Global Settings > Developer."] = "Oculta o pop-up de erro de Lua. A mesma configuração de Configurações Globais > Desenvolvedor."
L["Hide Error Messages"] = "Ocultar Mensagens de Erro"
L["Hides most red error messages (such as 'Not enough rage' or 'Ability is not ready yet'). Important errors like a full bag or quest log are still shown."] = "Oculta a maioria das mensagens de erro em vermelho (como 'Fúria insuficiente' ou 'Habilidade ainda não está pronta'). Erros importantes, como mochila cheia ou diário de missões cheio, continuam sendo exibidos."
L["Hide Talking Head"] = "Ocultar Cabeça Falante"
L["Hides the large NPC dialogue popup that appears during quests and dungeons."] = "Oculta o grande pop-up de diálogo de NPC que aparece durante missões e masmorras."
L["Hide Tutorial Pop-ups"] = "Ocultar Pop-ups de Tutorial"
L["Hides Blizzard's tutorial UI: the yellow HelpTip bubbles and the glowing (i) help-plate buttons on the spellbook, talents, map, collections, and other panels."] = "Oculta a interface de tutorial da Blizzard: os balões amarelos de dica e os botões de ajuda (i) brilhantes no livro de feitiços, talentos, mapa, coleções e outros painéis."
L["Hide Screenshot Status"] = "Ocultar Status de Captura de Tela"
L["Hides the 'Screenshot saved' notification that appears on screen after taking a screenshot."] = "Oculta a notificação 'Captura de tela salva' que aparece na tela após tirar uma captura de tela."
L["Displays a spoiler tag over guild chat in the communities window that you can click to hide"] = "Exibe uma etiqueta de spoiler sobre o bate-papo da guilda na janela de comunidades, que você pode clicar para ocultar"
L["Guild Chat Privacy Cover"] = "Cobertura de Privacidade do Bate-Papo da Guilda"

-- Auto Loot / Auto Repair / Auto Sell / Delete Confirmation
L["Quick Loot"] = "Saque Rápido"
L["Enables auto loot and hides the loot window when looting. Hold Shift when looting to show."] = "Ativa o saque automático e oculta a janela de saque ao saquear. Segure Shift ao saquear para exibi-la."
L["Auto-Fill Delete Confirmation"] = "Preencher Confirmação de Exclusão Automaticamente"
L["Automatically types DELETE when throwing away a valuable item. Also allows you to press enter to accept the deletion."] = "Digita DELETE automaticamente ao descartar um item valioso. Também permite pressionar Enter para confirmar a exclusão."
L["Auto Repair"] = "Reparo Automático"
L["Automatically repair all gear when visiting a repair vendor."] = "Repara automaticamente todo o equipamento ao visitar um vendedor de reparos."
L["Auto Repair Settings"] = "Configurações de Reparo Automático"
L["Use Guild Bank Funds"] = "Usar Fundos do Banco da Guilda"
L["Repair %"] = "Reparo %"
L["Auto Sell Junk"] = "Vender Lixo Automaticamente"
L["Automatically sell all junk items when visiting a vendor."] = "Vende automaticamente todos os itens de lixo ao visitar um vendedor."
L["Low Durability Warning"] = "Aviso de Baixa Durabilidade"
L["Flashes a warning on screen when any equipped item drops below the configured durability threshold. Only triggers out of combat."] = "Exibe um aviso piscante na tela quando qualquer item equipado cai abaixo do limite de durabilidade configurado. Só é acionado fora de combate."
L["Preview durability warning"] = "Prévia do aviso de durabilidade"
L["Durability Settings"] = "Configurações de Durabilidade"

-- Auto Open Containers / Auto Unwrap Collections / Warbound
L["Auto Open Containers"] = "Abrir Recipientes Automaticamente"
L["Automatically opens bags, boxes and parcels in your inventory when they are added to your bags.\n\nContainers received from the mailbox are held until you close the mailbox, so opening them cannot collide with mail still delivering items."] = "Abre automaticamente bolsas, caixas e pacotes em seu inventário quando são adicionados às suas mochilas.\n\nRecipientes recebidos pelo correio ficam retidos até você fechar a caixa de correio, para que abri-los não colida com correspondências ainda entregando itens."
L["Auto Open Containers Settings"] = "Configurações de Abertura Automática de Recipientes"
L["Exclude Warbound Containers"] = "Excluir Recipientes Vinculados à Conta"
L["Auto Unwrap Collections"] = "Desembrulhar Coleções Automaticamente"
L["Automatically dismisses the 'new mount/pet/toy' fanfare notification when you receive one, so you don't have to click through the collections journal."] = "Dispensa automaticamente a notificação de fanfarra de 'nova montaria/mascote/brinquedo' ao recebê-la, para que você não precise clicar pelo diário de coleções."

-- Auction House / Artisan / Profession trainers
L["AH Current Expansion Only"] = "Casa de Leilões: Apenas Expansão Atual"
L["Automatically enables the 'Current Expansion Only' filter whenever you open the Auction House."] = "Ativa automaticamente o filtro 'Apenas Expansão Atual' sempre que você abre a Casa de Leilões."
L["Hold Capped Artisan Payouts"] = "Reter Pagamentos do Consórcio no Limite"
L["Keeps Artisan's Consortium Payouts closed while Shard of Dundun is at its maximum, then resumes automatic opening after you spend shards."] = "Mantém os Pagamentos do Consórcio dos Artesãos fechados enquanto o Fragmento de Dundun estiver no máximo, retomando a abertura automática depois que você gastar fragmentos."
L["Adds a 'Train All' button next to the Train button at profession trainers, allowing you to learn all available skills with one click."] = "Adiciona um botão 'Aprender Tudo' ao lado do botão Aprender nos instrutores de profissão, permitindo aprender todas as habilidades disponíveis com um clique."
