-- Raid buff logic / glow options
L["Others are missing my buff: remind when a groupmate is missing a buff you can cast.\nI am missing others' buffs: remind when you are missing a buff a groupmate could give you (only shown when someone who can cast it is present). Off by default."] = "Outros estão sem meu buff: avisa quando um membro do grupo está sem um buff que você pode conceder.\nEstou sem buffs de outros: avisa quando você está sem um buff que um membro do grupo poderia te dar (só aparece quando há alguém que possa concedê-lo presente). Desativado por padrão."
L["This option only affects Raid Buffs and Paladin Beacons"] = "Esta opção afeta apenas Buffs de Raide e Focos de Paladino"
L["This option requires a Glow Type other than None"] = "Esta opção exige um Tipo de Brilho diferente de Nenhum"

