L["Create New (Copy)"] = "Criar Novo (Cópia)"
L["\"%1$s\" was saved but cannot be loaded because this spec has an assigned profile."] = "\"%1$s\" foi salvo, mas não pode ser carregado porque esta especialização tem um perfil atribuído."
L["\"%1$s\" was saved but cannot be loaded because this spec has an assigned profile. Switch specs or remove the spec assignment to use it."] = "\"%1$s\" foi salvo, mas não pode ser carregado porque esta especialização tem um perfil atribuído. Troque de especialização ou remova a atribuição de especialização para usá-lo."
L["Check Tanks"] = "Marcar Tanques"
