L["A sync group needs at least two profiles"] = "Um grupo de sincronização precisa de pelo menos dois perfis"
L["Coming soon"] = "Em breve"
L["In Maintenance"] = "Em Manutenção"
L["No other profiles to sync to"] = "Nenhum outro perfil para sincronizar"
L["No Profile Level Customizations"] = "Sem Personalizações no Nível de Perfil"
L["Shift+Middle Click to always show all settings"] = "Shift+Clique do Meio para sempre exibir todas as configurações"
L["This module can't be overridden. Exit the override editing session to open it."] = "Este módulo não pode ser substituído. Saia da sessão de edição de substituição para abri-lo."
L["This option is only available for the Custom Color Theme"] = "Esta opção só está disponível para o Tema de Cor Personalizada"
L["Delete the custom Debuff Manager for '%s'? Its specs return to your default Debuff Manager."] = "Excluir o Gerenciador de Debuffs personalizado de '%s'? As especializações dele voltam para o seu Gerenciador de Debuffs padrão."
L["Delete the custom Debuff Manager for '%s'? Its conditions return to your default Debuff Manager."] = "Excluir o Gerenciador de Debuffs personalizado de '%s'? As condições dele voltam para o seu Gerenciador de Debuffs padrão."
L["Are you sure you want to reset ALL EUI addon settings to their defaults? This will reload your UI."] = "Tem certeza de que deseja redefinir TODAS as configurações dos addons EUI para o padrão? Isso recarregará sua interface."
L["Better Character Panel conflicts with the EllesmereUI's Character Sheet. Disable either Better Character Panel or the Character Sheet skin in Blizzard UI Enhanced settings."] = "O Better Character Panel entra em conflito com a Ficha de Personagem da EllesmereUI. Desative o Better Character Panel ou a aparência da Ficha de Personagem nas configurações de Interface Blizz aprimorada."
L["Blizzard's Edit Mode snapping may not work correctly until you reload your UI."] = "O encaixe do Modo de Edição da Blizzard pode não funcionar corretamente até você recarregar sua interface."
L["Changing the language requires a UI reload."] = "Alterar o idioma requer recarregar a interface."
L["Chonky Character Sheet conflicts with the EllesmereUI's Character Sheet. Disable either Chonky or the Character Sheet skin in Blizzard UI Enhanced settings."] = "O Chonky Character Sheet entra em conflito com a Ficha de Personagem da EllesmereUI. Desative o Chonky ou a aparência da Ficha de Personagem nas configurações de Interface Blizz aprimorada."
L["Clique controls click-casting on the same Raid Frames as EllesmereUI's HoverCast, so they conflict. Disable the Clique addon to use HoverCast."] = "O Clique controla o lançamento por clique nos mesmos Quadros de Raide que o HoverCast da EllesmereUI, então eles entram em conflito. Desative o addon Clique para usar o HoverCast."
L["Combat text font changes require a logout to character select to take effect. This is a WoW engine limitation."] = "Alterações na fonte do texto de combate exigem logout até a tela de seleção de personagem para ter efeito. Esta é uma limitação do motor do WoW."
L["Deja Character Stats conflicts with the EllesmereUI's Character Sheet. Disable either Deja or the Character Sheet skin in Blizzard UI Enhanced settings."] = "O Deja Character Stats entra em conflito com a Ficha de Personagem da EllesmereUI. Desative o Deja ou a aparência da Ficha de Personagem nas configurações de Interface Blizz aprimorada."
L["EllesmereUI WonderBar was renamed to EllesmereUI DataBars. The old WonderBar addon is still installed and both create the same bar. Please disable or delete the EllesmereUIWonderBar addon."] = "O EllesmereUI WonderBar foi renomeado para EllesmereUI DataBars. O addon antigo WonderBar ainda está instalado, e ambos criam a mesma barra. Desative ou exclua o addon EllesmereUIWonderBar."
L["idTip conflicts with EllesmereUI's tooltip systems. Disable the idTip addon to stay compatible."] = "O idTip entra em conflito com os sistemas de dicas de ferramenta da EllesmereUI. Desative o addon idTip para manter a compatibilidade."
L["Leatrix Plus has chat and minimap features that conflict with EllesmereUI. Disable any chat or minimap related options within Leatrix Plus to stay compatible."] = "O Leatrix Plus tem recursos de bate-papo e minimapa que entram em conflito com a EllesmereUI. Desative quaisquer opções relacionadas a bate-papo ou minimapa dentro do Leatrix Plus para manter a compatibilidade."
L["Many of ElvUI's modules are incompatible with EllesmereUI. Make sure to disable any conflicting modules."] = "Muitos módulos do ElvUI são incompatíveis com a EllesmereUI. Certifique-se de desativar quaisquer módulos conflitantes."
L["Name font changes require a logout to character select to take effect. This is a WoW engine limitation."] = "Alterações na fonte de nomes exigem logout até a tela de seleção de personagem para ter efeito. Esta é uma limitação do motor do WoW."
L["TellMeWhen overlaps with EllesmereUI's core positional architecture. If you ONLY use for sound alerts it should be okay but may still cause issues."] = "O TellMeWhen se sobrepõe à arquitetura posicional principal da EllesmereUI. Se você o usa APENAS para alertas sonoros, deve funcionar bem, mas ainda pode causar problemas."
L["UI scale set to 0.5333. A reload is recommended."] = "Escala da interface definida para 0.5333. É recomendado recarregar."
L["This resets every EUI addon, not just the current one."] = "Isso redefine todos os addons EUI, não apenas o atual."
L["This will not reset addon-specific Quick Setup."] = "Isso não redefine a Configuração Rápida específica do addon."
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\nShadow Quality - Fair (balanced quality/FPS)\nLiquid Detail - Disabled\nParticle Density - Set to Ultra (keeps important spell effects)\nSSAO (Ambient Occlusion) - Disabled\nDepth Effects - Disabled\nCompute Effects - Disabled\nOutline Mode - Disabled\nTexture Resolution - Set to High\nSpell Density - Set to Essential\nProjected Textures - Enabled (needed for ground effects)\nView Distance - Reduced to 1\nEnvironment Detail - Reduced to 1\nGround Clutter - Reduced to 1\nRaid/Dungeon Settings - Uses same settings everywhere\nResample Sharpening - Enabled (crisper image)\nContrast - Boosted by +10 (if currently 55 or below)\nEnable Reverb - Disabled (spell and interrupt audio cues stay crisp)\n\nThese settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "Este recurso otimiza as configurações gráficas do jogo para dar a você a melhor combinação de FPS alto e clareza visual.\n\nVocê pode reverter todas as alterações a qualquer momento clicando em \"Restaurar Minhas Configurações\", que aparecerá após a otimização.\n\n\nO que mudamos:\n\nQualidade de Sombra - Razoável (equilíbrio entre qualidade/FPS)\nDetalhe de Líquidos - Desativado\nDensidade de Partículas - Definida como Ultra (mantém efeitos de feitiços importantes)\nSSAO (Oclusão de Ambiente) - Desativado\nEfeitos de Profundidade - Desativado\nEfeitos de Computação - Desativado\nModo de Contorno - Desativado\nResolução de Textura - Definida como Alta\nDensidade de Feitiços - Definida como Essencial\nTexturas Projetadas - Ativado (necessário para efeitos no chão)\nDistância de Visão - Reduzida para 1\nDetalhe de Ambiente - Reduzido para 1\nVegetação Rasteira - Reduzida para 1\nConfigurações de Raide/Masmorra - Usa as mesmas configurações em todo lugar\nNitidez de Reamostragem - Ativado (imagem mais nítida)\nContraste - Aumentado em +10 (se atualmente 55 ou menos)\nAtivar Reverberação - Desativado (sinais sonoros de feitiços e interrupções continuam nítidos)\n\nEssas configurações priorizam taxa de quadros e clareza visual em detrimento do detalhe ambiental. As texturas permanecem em alta qualidade, então seu personagem e o mundo continuam parecendo perfeitos."

