L["Applies your Global Font to Blizzard's default game text (menus, tooltips, quest log, character panes, and more). Requires a UI reload."] = "Aplica sua Fonte Global ao texto padrão do jogo da Blizzard (menus, dicas, diário de missões, painéis de personagem e mais). Requer recarregar a interface."
