L["Name Font"] = "Fonte de Nome"
L["On (default): one profile's palette is shared across every profile (chosen via Pull Colors From). Off: each profile keeps its own custom colors (Power, Class Resource, Class, Resource)."] = "Ativado (padrão): a paleta de um perfil é compartilhada entre todos os perfis (escolhido via Copiar Cores De). Desativado: cada perfil mantém suas próprias cores personalizadas (Poder, Recurso de Classe, Classe, Recurso)."
L["Only Hide Fully Synced"] = "Ocultar Apenas Totalmente Sincronizados"
L["Outline Icon Text"] = "Contornar Texto do Ícone"
L["Power Color Darken"] = "Escurecimento de Cor de Poder"
L["Prevent Swiftmend Icon Dim"] = "Evitar Escurecimento do Ícone de Recomposição Rápida"
L["Prevents Blizzard from dimming Swiftmend on action bars and CDM based on Efflorescence state."] = "Impede que a Blizzard escureça Recomposição Rápida nas barras de ação e no CDM com base no estado de Eflorescência."
L["Pull Colors From"] = "Copiar Cores De"
L["Raid Frames Icons"] = "Ícones de Quadros de Raide"
L["Reset ALL Settings"] = "Redefinir TODAS as Configurações"
L["Resource Color Darken"] = "Escurecimento de Cor de Recurso"
L["Set UI Scale to 0.5333"] = "Definir Escala da Interface para 0.5333"
L["Sets the UI scale to the exact pixel-perfect value used by other addons. EllesmereUI does not require this to be pixel perfect."] = "Define a escala da interface para o valor exato de pixel perfeito usado por outros addons. A EllesmereUI não exige que seja pixel perfeito."
L["Sets the accent color used across all EllesmereUI elements (tabs, glows, highlights, borders). Defaults to your theme color."] = "Define a cor de destaque usada em todos os elementos da EllesmereUI (abas, brilhos, realces, bordas). O padrão é a cor do seu tema."
L["Sets the font for the names that float above players, NPCs and enemies in the world.\n\nSeparate from Global Font - changing this does not affect the rest of the UI, and Global Font does not affect it.\n\nBlizzard Default leaves the name text completely untouched.\n\n|cffff4d4dRequires a re-log or restart of WoW to take effect.|r"] = "Define a fonte para os nomes que flutuam acima de jogadores, NPCs e inimigos no mundo.\n\nSepara da Fonte Global - alterar isso não afeta o resto da interface, e a Fonte Global não a afeta.\n\nPadrão da Blizzard deixa o texto do nome completamente intocado.\n\n|cffff4d4dRequer relogar ou reiniciar o WoW para ter efeito.|r"
L["Sets the scale of the entire game UI. Lower values make everything smaller, higher values make everything larger."] = "Define a escala de toda a interface do jogo. Valores menores deixam tudo menor; valores maiores deixam tudo maior."
L["Show Combat Damage Text"] = "Exibir Texto de Dano de Combate"
L["Show Combat Healing Text"] = "Exibir Texto de Cura de Combate"
