-- == General Options / Profile Import & Export Include Tips =====================
L["This profile string does not carry any override data."] = "Esta string de perfil não contém nenhum dado de substituição."
L["This profile string does not carry any Window & Tooltip Skins settings."] = "Esta string de perfil não contém nenhuma configuração de Aparências de Janelas e Dicas de Ferramenta."
L["Import the sharer's complete override setup: spec and conditional override values, groups, their custom Unlock Mode layouts, and Buff Manager overrides. This replaces ALL of your own overrides. Off = keep yours untouched."] = "Importa a configuração completa de substituições de quem compartilhou: valores de substituição por especialização e condicional, grupos, seus Modos de Desbloqueio personalizados e substituições do Gerenciador de Buffs. Isso substitui TODAS as suas próprias substituições. Desativado = mantém as suas inalteradas."
L["Import the anchor & size-match relationships from this profile. Off = keep your own layout; only the selected modules' own positions/settings come in."] = "Importa as relações de âncora e correspondência de tamanho deste perfil. Desativado = mantém seu próprio layout; apenas as posições/configurações próprias dos módulos selecionados são importadas."
L["Apply the sharer's fonts, custom colours, dark mode, accent colour and UI scale. Off = keep your own global look and scale; only the selected modules' settings come in."] = "Aplica as fontes, cores personalizadas, modo escuro, cor de destaque e escala da interface de quem compartilhou. Desativado = mantém sua própria aparência global e escala; apenas as configurações dos módulos selecionados são importadas."
L["Apply the sharer's Blizz UI Enhanced Window Skins and Tooltips, Menus & Popups settings. These are account-wide and will overwrite yours across ALL profiles. Off = keep your own."] = "Aplica as configurações de Interface Blizz Aprimorada (abas Aparência de Janelas e Dicas de Ferramenta, Menus e Pop-ups) de quem compartilhou. Essas configurações são de toda a conta e substituirão as suas em TODOS os perfis. Desativado = mantém as suas."
L["Include your complete override setup: spec and conditional override values, groups, their custom Unlock Mode layouts, and Buff Manager overrides. On import this replaces the recipient's overrides entirely."] = "Inclui sua configuração completa de substituições: valores de substituição por especialização e condicional, grupos, seus Modos de Desbloqueio personalizados e substituições do Gerenciador de Buffs. Na importação, isso substitui totalmente as substituições de quem importar."
L["Include the anchor & size-match relationships between modules. Off = export each module's own positions only, with no cross-module tying."] = "Inclui as relações de âncora e correspondência de tamanho entre módulos. Desativado = exporta apenas as posições próprias de cada módulo, sem vínculo entre módulos."
L["Include fonts, custom colours, dark mode, accent colour and UI scale with this export. Off = only the selected modules' own settings export, keeping the recipient's global look."] = "Inclui fontes, cores personalizadas, modo escuro, cor de destaque e escala da interface nesta exportação. Desativado = exporta apenas as próprias configurações dos módulos selecionados, mantendo a aparência global de quem importar."
L["Include your Blizz UI Enhanced settings from the Window Skins and Tooltips, Menus & Popups tabs. These are account-wide: if the importer opts in, they overwrite that player's settings across ALL of their profiles."] = "Inclui suas configurações de Interface Blizz Aprimorada das abas Aparência de Janelas e Dicas de Ferramenta, Menus e Pop-ups. Essas configurações são de toda a conta: se quem importar optar por isso, elas substituirão as configurações desse jogador em TODOS os seus perfis."

