-- == Options / Font & Texture Settings -- tooltips =============================
L["Draw a 1px divider between the spell icon and the cast bar, matching the border color."] = "Desenha um divisor de 1px entre o ícone do feitiço e a barra de lançamento, combinando com a cor da borda."
L["Hide the 1-pixel border around the cast bar spell icon."] = "Oculta a borda de 1 pixel ao redor do ícone de feitiço da barra de lançamento."
