L["Debuffs with the Poison dispel type."] = "Debuffs com o tipo de dissipação Veneno."
L["Debuffs your own class is able to apply."] = "Debuffs que sua própria classe é capaz de aplicar."
L["Max Duration"] = "Duração Máxima"
