-- == ptBR Batch 2 (2026-09-15/16): master_keys.txt audit-verified entries ==
-- Verified via exact string-literal matching against every non-locale .lua
-- file (not just substring containment -- see session report for why that
-- distinction matters). "'s skin requires a UI reload." was excluded even
-- though it passed the exact-literal check: it's a real Lua string token
-- in source, but only as one piece of a runtime concatenation
-- ("Removing " .. name .. "'s skin requires a UI reload."), so L() never
-- receives it standalone and it can never match a locale key.
