L["Off (default): the cast bar fades with real transparency, matching the whole-frame Out of Range Alpha (best if you're colour-matching the frame and cast bar). On: the old behavior -- a black overlay dims the bar instead of fading it, which can't discolor a shielded/uninterruptible cast's tint but won't visually match the frame's fade."] = "Desativado (padrão): a barra de conjuração esmaece com transparência real, correspondendo à Opacidade Fora de Alcance de todo o quadro (melhor se você estiver combinando a cor do quadro e da barra de conjuração). Ativado: o comportamento antigo -- uma sobreposição preta escurece a barra em vez de esmaecê-la, o que não consegue descolorir o tom de uma conjuração protegida/ininterrupta, mas não vai combinar visualmente com o esmaecimento do quadro."
