L["Out-of-range frames darken instead of fading transparent, matching Blizzard's default party/raid frame look. Uses the same Out of Range Alpha % as brightness: 100% = no visible difference in/out of range, 10% = out-of-range frames drop to 10% brightness."] = "Quadros fora de alcance escurecem em vez de esmaecer com transparência, combinando com a aparência padrão de quadro de grupo/raide da Blizzard. Usa a mesma % de Opacidade Fora de Alcance como brilho: 100% = nenhuma diferença visível dentro/fora de alcance, 10% = quadros fora de alcance caem para 10% de brilho."
