-- == ptBR Batch 3 (2026-09-16): master_keys.txt audit-verified entries ==
-- This batch's exact-verified candidate pool (245 keys) was further pruned
-- by 60 entries after checking each candidate's actual source call site,
-- not just literal existence: 40 were internal enum/search-index values
-- (shape ids, visibility mode ids, the settings-search keyword list) never
-- passed through L()/Lf() for display; 15 were EllesmereUI.Print()/print()
-- chat announcements that bypass L() entirely (an addon-source gap, not a
-- locale-file issue); 5 were fragments of runtime string concatenation
-- (tooltip text built from literal pieces joined with "..", where only the
-- full joined string -- never in master_keys.txt -- reaches L()). Full
-- list in the session report.
L["QoL Addons"] = "Addons de QoL" -- JARGAO
L["Quest objective progress no longer stops updating until a reload (a fishing count or summon bar stuck mid-way)."] = "O progresso do objetivo de missão não trava mais até uma recarga (uma contagem de pesca ou barra de invocação presa no meio do caminho)."
L["Racial spells assigned to a custom bar stay there through spec changes and relogs, and racials untracked in Blizzard's Cooldown Manager display again."] = "Feitiços raciais atribuídos a uma barra personalizada permanecem lá após mudanças de especialização e relogins, e raciais não rastreados no Gerenciador de Recarga da Blizzard voltam a ser exibidos."
L["Rage"] = "Raiva"
L["Raid Buff Whisper"] = "Sussurro de Buff de Raide" -- JARGAO
L["Raid CDs"] = "CDs de Raide" -- JARGAO
L["Raid Check Window Scale"] = "Escala da Janela de Verificação de Raide"
L["Raid Groups Window Scale"] = "Escala da Janela de Grupos de Raide"
L["Raid frame absorbs and health ticks, nameplate health updates, tracking bar pairing and unit frame absorbs all do less work per event"] = "Absorções do quadro de raide e atualizações de vida, atualizações de vida da placa de nome, pareamento de barra de rastreamento e absorções do quadro de unidade agora fazem menos trabalho por evento"
L["Raid only. Left-click the Durability column's header icon anytime to use the Auto-Hammer (item 132514) -- no one needs to be low first. When a player's Durability reading drops to 25% or below, their name blinks as a heads-up, but that's just a warning, not a requirement to click."] = "Somente em raide. Clique com o botão esquerdo no ícone do cabeçalho da coluna de Durabilidade a qualquer momento para usar o Auto-Martelo (item 132514) -- ninguém precisa estar com durabilidade baixa primeiro. Quando a leitura de Durabilidade de um jogador cai para 25% ou menos, o nome dele pisca como um aviso, mas isso é só um alerta, não um requisito para clicar."
L["Raid only. Left-click the Food column's header icon anytime to drop a feast at your own feet: Feast of Knowledge, falling back to Amani Cornucopia and then Loa's Gathering depending on what's in your bags. Disarmed while you already have a Well Fed buff active, so there's no wasted click."] = "Somente em raide. Clique com o botão esquerdo no ícone do cabeçalho da coluna de Comida a qualquer momento para soltar um banquete aos seus pés: Banquete do Conhecimento, recorrendo a Corno da Abundância Amani e depois Colheita de Loa dependendo do que você tem nas bolsas. Desarmado enquanto você já tiver um buff de Bem Alimentado ativo, então não há clique desperdiçado." -- JARGAO
L["Raises or lowers the tracker's frame strata. Increase it if other UI elements are drawing on top of the tracker; decrease it if the tracker is drawing on top of something it shouldn't."] = "Aumenta ou diminui a estrata do quadro do rastreador. Aumente se outros elementos da interface estiverem sendo desenhados sobre o rastreador; diminua se o rastreador estiver sendo desenhado sobre algo que não deveria."
L["Ravynne"] = true
L["Recent Avg"] = "Média Recente"
L["Recolors this boss frame's health bar fill with the color chosen below while it is your current target. Boss frames only."] = "Recolore o preenchimento da barra de vida deste quadro de chefe com a cor escolhida abaixo enquanto ele for seu alvo atual. Apenas quadros de chefe."
L["Reload required - close dropdown to reload"] = "Recarga necessária - feche o menu suspenso para recarregar"
L["Reloading the UI while in combat no longer causes script-ran-too-long errors and half-loaded modules."] = "Recarregar a interface durante o combate não causa mais erros de script demorado nem módulos parcialmente carregados."
L["Removes the block from the bar in instanced content, where player coordinates are unavailable."] = "Remove o bloco da barra em conteúdo instanciado, onde as coordenadas do jogador não estão disponíveis."
