L["Show the crafted quality rank on tracked items, matching the rank icon on the action bars. Items with no crafted quality are unaffected. Only shown while the item is owned."] = "Exibe o nível de qualidade de fabricação em itens rastreados, combinando com o ícone de nível nas barras de ação. Itens sem qualidade de fabricação não são afetados. Só é exibido enquanto o item é possuído."
L["Shows start as a small icon, and the keybind switches between the icon and the full windows. Turn off to show full windows and make the keybind hide and show them."] = "As janelas começam como um pequeno ícone, e o atalho alterna entre o ícone e as janelas completas. Desative para exibir as janelas completas e fazer o atalho ocultá-las e exibi-las."
L["Shows the Role Check button. Turn it off and the remaining buttons close the gap."] = "Exibe o botão de Verificação de Função. Desative para que os botões restantes fechem o espaço."
L["Shows the focus target's raid marker icon next to the cast bar itself, instead of (or in addition to) the frame-level marker in Extras."] = "Exibe o ícone de marcador de raide do alvo de foco ao lado da própria barra de conjuração, em vez de (ou além de) o marcador em nível de quadro em Extras."
L["Shows the window even when you can do nothing about what it reports. Every column is read from your own client, so this view is complete rather than degraded."] = "Exibe a janela mesmo quando você não pode fazer nada sobre o que ela reporta. Cada coluna é lida do seu próprio cliente, então essa visão é completa em vez de degradada."
