L["Target, Focus and Targeted Spell cast bars no longer truncate spell names when there is no target text sharing the bar."] = "As barras de conjuração de Alvo, Foco e Feitiço Alvejado não truncam mais os nomes dos feitiços quando não há texto de alvo compartilhando a barra."
