L["That setting is stored by list position and can't be safely overridden."] = "Essa configuração é armazenada pela posição na lista e não pode ser substituída com segurança."
L["The Battle.net friend online and offline toast gets a window skin, with its own Friend Notifications card"] = "O aviso de amigo do Battle.net online e offline agora tem um estilo de janela, com seu próprio cartão de Notificações de Amigos"
L["The Cooldown Manager can do far more than show cooldowns, it also has per-spell settings, bar glows, tracking bars and more! Check out some tips and tricks for getting more from it."] = "O Gerenciador de Recarga pode fazer muito mais do que exibir recargas, ele também tem configurações por feitiço, brilhos de barra, barras de rastreamento e mais! Confira algumas dicas e truques para aproveitar ao máximo."
L["The LFG Reminder popup now matches dungeon names on every client language, not only English and Russian."] = "O popup de Lembrete de LFG agora reconhece nomes de masmorra em qualquer idioma do cliente, não apenas inglês e russo." -- JARGAO
L["The Missing Pet reminder no longer appears while mounted or flashes on dismount."] = "O lembrete de Pet Ausente não aparece mais enquanto montado nem pisca ao desmontar."
L["The Whirlwind and Sweeping Strikes bar honors the Empty Bar Overlay again so spent charges show in Dark Mode, no longer draws a second set of divider lines with Bar Spacing set, hides its threshold strip while thresholds are disabled, and accepts a stack threshold up to 20."] = "A barra de Turbilhão e Investidas Arrasadoras agora respeita a Sobreposição de Barra Vazia, então cargas gastas aparecem no Modo Escuro, não desenha mais um segundo conjunto de linhas divisórias quando o Espaçamento de Barra está definido, oculta sua faixa de limite enquanto os limites estão desativados, e aceita um limite de pilha de até 20."
L["The active override's Buff Manager is bound to the open page. Leave the Buff Manager tab to switch overrides."] = "O Gerenciador de Buffs da substituição ativa está vinculado à página aberta. Saia da aba do Gerenciador de Buffs para trocar de substituição." -- JARGAO
L["The bank window catches up to the bags: nest OneBank and OneWarbank by expansion, group items by your bag categories with automatic splits by equipment slot, profession and material, and browse a category sidebar that spans your character bank and warband together."] = "A janela do banco agora acompanha as bolsas: aninha OneBank e OneWarbank por expansão, agrupa itens pelas suas categorias de bolsa com divisões automáticas por espaço de equipamento, profissão e material, e navega por uma barra lateral de categorias que abrange seu banco de personagem e o banco de guerra juntos."
L["The override group '%s' already provides the custom unlock mode for your current spec. Customize it there, or remove this spec from that group."] = "O grupo de substituição '%s' já fornece o modo de desbloqueio personalizado para sua especialização atual. Personalize-o lá, ou remova esta especialização desse grupo."
L["The pet frame updates its name and portrait when you swap pets (for example Voidwalker to Felhunter)."] = "O quadro do pet atualiza seu nome e retrato quando você troca de pet (por exemplo, de Andarilho do Vazio para Caçador Infernal)."
L["The refresh rate now bottoms out at 0.5s (lower saved values move up to it), trimming memory churn during combat."] = "A taxa de atualização agora tem um piso de 0,5s (valores salvos menores sobem até ele), reduzindo o consumo de memória durante o combate."
L["The target effect's border size no longer snaps back to normal while a cast bar is shown with Border Wraps Around Cast Bar enabled."] = "O tamanho da borda do efeito de alvo não volta mais ao normal enquanto uma barra de conjuração é exibida com Borda Envolve a Barra de Conjuração ativado."
L["These settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "Essas configurações priorizam a taxa de quadros e a clareza visual em vez do detalhe ambiental. As texturas permanecem em alta qualidade para que seu personagem e o mundo continuem parecendo perfeitos."
L["Thin Line Bottom"] = "Linha Fina Inferior"
L["Thin Line Top"] = "Linha Fina Superior"
L["This Setting Has Overrides"] = "Esta Configuração Tem Substituições"
L["This cannot be undone. Consider exporting this profile as a backup first."] = "Isso não pode ser desfeito. Considere exportar este perfil como backup primeiro."
L["This conditional is not active right now. Meet one of its conditions first (for example, enter the dungeon) so you can arrange the layout in its real context."] = "Este condicional não está ativo no momento. Cumpra uma de suas condições primeiro (por exemplo, entre na masmorra) para poder organizar o layout em seu contexto real."
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\n"] = "Este recurso otimiza as configurações gráficas do seu jogo para oferecer a melhor combinação de FPS alto e clareza visual.\n\nVocê pode reverter todas as mudanças a qualquer momento clicando em \"Restaurar Minhas Configurações\", que aparecerá após a otimização.\n\n\nO que mudamos:\n\n"
L["This group's custom Buff Manager can only be activated or edited while playing one of its specs."] = "O Gerenciador de Buffs personalizado deste grupo só pode ser ativado ou editado enquanto você estiver jogando uma de suas especializações." -- JARGAO
L["This module is excluded from Spec Overrides."] = "Este módulo está excluído das Substituições de Especialização."
L["This permanently overwrites this profile's settings with the override '%s': its captured settings and its custom Unlock Mode and Buff Manager layouts (where present) become the profile's own baseline for every spec. ALL spec override groups on this profile are then deleted and the UI reloads. Conditional overrides are not affected."] = "Isso substitui permanentemente as configurações deste perfil pela substituição '%s': suas configurações capturadas e seus layouts personalizados de Modo de Desbloqueio e Gerenciador de Buffs (quando presentes) se tornam a base do próprio perfil para cada especialização. TODOS os grupos de substituição de especialização deste perfil são então excluídos e a interface recarrega. Substituições condicionais não são afetadas." -- JARGAO
L["This setting already has an override for %s"] = "Esta configuração já tem uma substituição para %s"
L["This setting can't be overridden."] = "Esta configuração não pode ser substituída."
L["This spec's custom unlock mode is owned by '%s'. Customize it there, or remove the spec from that group."] = "O modo de desbloqueio personalizado desta especialização pertence a '%s'. Personalize-o lá, ou remova a especialização desse grupo."
L["This will create a fully unique unlock mode for this conditional group. Changes made to your default unlock mode will no longer affect it."] = "Isso criará um modo de desbloqueio totalmente exclusivo para este grupo condicional. Alterações feitas no seu modo de desbloqueio padrão não vão mais afetá-lo."
L["This will create a fully unique unlock mode for this override group. Changes made to your default unlock mode will no longer affect these specs."] = "Isso criará um modo de desbloqueio totalmente exclusivo para este grupo de substituição. Alterações feitas no seu modo de desbloqueio padrão não vão mais afetar essas especializações."
L["Threshold and band colors work on the Whirlwind and Sweeping Strikes charge bar again, drawn as color ranges along the fill"] = "As cores de limite e faixa voltam a funcionar na barra de cargas de Turbilhão e Investidas Arrasadoras, desenhadas como intervalos de cor ao longo do preenchimento"
