L["Which layer the windows and the collapsed icon draw on, relative to other frames on screen."] = "Em qual camada as janelas e o ícone recolhido são desenhados, em relação a outros quadros na tela."
L["Which way spell flyouts (e.g. Wild Mushroom, Tiger's Fury) open from this bar. Automatic opens away from the nearest screen edge."] = "Para que lado os flyouts de feitiço (ex.: Cogumelo Selvagem, Fúria do Tigre) abrem a partir desta barra. Automático abre para longe da borda de tela mais próxima." -- JARGAO
