L["With health decimals on, full health renders 100% instead of 100.0% while real decimals like 99.5% stay"] = "Com decimais de vida ativados, vida cheia é exibida como 100% em vez de 100,0%, enquanto decimais reais como 99,5% permanecem"
L["With the Rectangular shape, player and party arrows no longer draw in the hidden bands above and below the map, and combat transitions no longer leave the map cut off wrong."] = "Com o formato Retangular, as setas de jogador e grupo não são mais desenhadas nas faixas ocultas acima e abaixo do mapa, e as transições de combate não deixam mais o mapa cortado incorretamente."
L["Works in and out of combat, unlike Auto-Repair. When a group-wide raid buff's column header shows it's missing on someone, the icon blinks and sends the buff's spell link. In a raid, left-click reaches a provider in groups 1-4 and right-click one in groups 5-8; outside a raid, left-click reaches the only provider found. Hovering the icon always shows who each click would whisper, or that everyone already has it."] = "Funciona dentro e fora de combate, diferente do Auto-Reparo. Quando o cabeçalho de coluna de um buff de raide em grupo mostra que está faltando em alguém, o ícone pisca e envia o link do feitiço do buff. Em uma raide, clique esquerdo alcança um provedor nos grupos 1-4 e clique direito um nos grupos 5-8; fora de uma raide, o clique esquerdo alcança o único provedor encontrado. Passar o mouse sobre o ícone sempre mostra a quem cada clique enviaria um sussurro, ou que todos já o têm." -- JARGAO
