L["You changed the default value of a setting that has overrides. Overrides keep their own values, so this change will not reach the specs or conditions they cover. To change it for an override, pick that override from the class glyph beside the module search bar and edit it there."] = "Você alterou o valor padrão de uma configuração que tem substituições. As substituições mantêm seus próprios valores, então essa alteração não chegará às especializações ou condições que elas cobrem. Para alterá-la em uma substituição, escolha essa substituição no glifo de classe ao lado da barra de busca de módulos e edite-a lá."
