L["A new built-in profile preset: the damage dealer cut of Midnight Lily, a focused low-clutter layout that keeps your rotation and cooldowns front and center."] = "Uma nova predefinição de perfil integrada: a versão para causadores de dano do Midnight Lily, um layout focado e com pouca poluição visual que mantém sua rotação e recargas em destaque."
L["A new option that makes enemy nameplates pulse with a red glow the moment a target drops below 30% health, so a whole pack tells you at a glance which mobs are in execute range."] = "Uma nova opção que faz as placas de nome inimigas pulsarem com um brilho vermelho no momento em que um alvo cai abaixo de 30% de vida, para que todo o grupo de mobs mostre de relance quais estão na faixa de execução."
