L["Closes an open menu without using anything. Escape always does this as well. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time.\n\nLeft-click to set a keybind, then press any key or\nclick any mouse button to use it.\nEscape cancels. Right-click here to unbind."] = "Fecha um menu aberto sem usar nada. Escape sempre faz isso também. Uma tecla compartilhada por todos os menus, reivindicada apenas enquanto um menu está aberto -- um botão do mouse mantém seu uso normal no resto do tempo.\n\nClique com o botão esquerdo para definir uma tecla de atalho, depois pressione qualquer tecla ou\nclique em qualquer botão do mouse para usá-la.\nEscape cancela. Clique com o botão direito aqui para desvincular."
