-- == ptBR Batch 4 (2026-09-16): master_keys.txt diff, alphabetical range "Dispel Icons" .. "Intellect %d" ==
-- 8 keys from this alphabetical range excluded as confirmed phantom/dead.
-- 2 are the same already-documented fragments from earlier batches
-- ("'s Death Recap", "'s skin requires a UI reload."). 6 are NEW findings,
-- each individually confirmed by a full-repo grep (outside EllesmereUILocales)
-- returning zero hits, or a mismatched-accent real source string:
--   "GROUPSETTINGS", "GlobalColorsHelp", "Got lt": zero hits anywhere in the
--     addon source (not even "Got it"). No call site can ever look these up.
--   "Espanol (EU)", "Espanol (LatAm)": the real source string (verified at
--     EllesmereUIOptions/EUI__General_Options.lua:4043-4044) is the accented
--     "Español (EU)" / "Español (LatAm)" -- same bug family as the
--     documented "Portugues (BR)" vs "Português (BR)" phantom in
--     known_issues.md, just for Spanish instead of Portuguese.
--   "Francais": the real source string (verified at
--     EllesmereUIOptions/EUI__General_Options.lua:4042) is the accented
--     "Français". Same bug family as above.
-- All 6 new ones originate only from the pre-project zhCN.lua snapshot per
-- audit_sem_correspondencia.txt (LOCALES_ORIGINAIS=zhCN for the first 3),
-- consistent with the known "inherited junk" pattern already documented for
-- other locales in known_issues.md. Flagged for the maintainer/locale-planner
-- to fold into known_issues.md and master_keys.txt if desired -- out of this
-- translator session's own scope to edit those shared files.
