L["Recolor the bar while you have a buff. The first active buff in the list wins, so order = priority. Overrides threshold coloring while active.\nYou must be tracking the buff in Blizzard CDM, added to EUI CDM, and this only works with CDM trackable buffs."] = "Recolore a barra enquanto você tem um buff. O primeiro buff ativo na lista vence, então ordem = prioridade. Substitui a coloração por limite enquanto ativo.\nVocê precisa estar rastreando o buff no CDM da Blizzard, adicionado ao CDM da EUI, e isso só funciona com buffs rastreáveis pelo CDM."
L["Recolors headers, arrows, and spell titles in Blizzard tooltips and context menus to match your UI Accent Color."] = "Recolore cabeçalhos, setas e títulos de feitiço nas dicas de ferramenta e menus de contexto da Blizzard para combinar com sua Cor de Destaque da interface."
L["Refresh using tooltip scan data.\n For exact costs, use |cffffffff'Update at Upgrader'|r\n while at an Item Upgrade NPC."] = "Atualiza usando os dados de varredura da dica de ferramenta.\n Para custos exatos, use |cffffffff'Atualizar no Melhorador'|r\n enquanto estiver em um NPC de Melhoria de Item."
