L["Show the part of an absorb that exceeds your empty health and backfills over your current health. When off, absorbs only fill the empty part of the health bar."] = "Mostra a parte de uma absorção que excede sua vida vazia e preenche por trás sobre sua vida atual. Quando desativado, as absorções preenchem apenas a parte vazia da barra de vida."
L["Show the part of an absorb that exceeds your empty health and backfills over your current health. When off, absorbs only fill the empty part of the health bar; on Default Blizz Frames the glow line stays pinned at the right edge."] = "Mostra a parte de uma absorção que excede sua vida vazia e preenche por trás sobre sua vida atual. Quando desativado, as absorções preenchem apenas a parte vazia da barra de vida; nos Quadros Padrão da Blizz, a linha de brilho permanece fixa na borda direita."
L["Show the player's title or guild in a smaller line below their name on friendly nameplates."] = "Mostra o título ou a guilda do jogador em uma linha menor abaixo do nome dele nas placas de nome amigáveis."
L["Show while this condition is false"] = "Mostrar enquanto esta condição for falsa"
L["Show world latency instead of home latency."] = "Mostra a latência mundial em vez da latência local."
L["Shows a countdown bar below the queue accept popup indicating how long you have to accept. Works with or without the reskin. Use the swatch and cog to set the countdown text color, text size. bar height and text offset."] = "Mostra uma barra de contagem regressiva abaixo do pop-up de aceitação de fila, indicando quanto tempo você tem para aceitar. Funciona com ou sem a reestilização. Use a amostra e a engrenagem para definir a cor do texto de contagem regressiva, o tamanho do texto, a altura da barra e o deslocamento do texto."
