L["Thank you for helping test EllesmereUI during beta! During testing, many systemic changes were made to build the foundation for a stable, flexible addon going forward.\n\nTo ensure a clean experience for everyone, all settings have been automatically reset. You will need to reconfigure your UI. We apologize for the inconvenience, and appreciate your patience.\n\nPrevious profile exports are no longer compatible and will need to be re-created."] = "Obrigado por ajudar a testar o EllesmereUI durante o beta! Durante os testes, muitas mudanças sistêmicas foram feitas para construir a base de um addon estável e flexível daqui em diante.\n\nPara garantir uma experiência limpa para todos, todas as configurações foram redefinidas automaticamente. Você precisará reconfigurar sua interface. Pedimos desculpas pelo inconveniente e agradecemos sua paciência.\n\nExportações de perfil anteriores não são mais compatíveis e precisarão ser recriadas."
