L["The active override's custom Buff Manager is bound to this page. Leave the Buff Manager tab to switch to another override."] = "O Gerenciador de Buffs personalizado da substituição ativa está vinculado a esta página. Saia da aba Gerenciador de Buffs para trocar para outra substituição."
L["The class resource bar gains a spec picker to choose which specs show it, matching the power and health bars."] = "A barra de recurso de classe ganha um seletor de especialização para escolher em quais especializações ela aparece, igualando as barras de poder e vida."
L["The default EllesmereUI look"] = "A aparência padrão do EllesmereUI"
L["The dispel type icon gains an Icon Size slider in its cog menu so you can make it larger or smaller."] = "O ícone de tipo de dissipação ganha um controle deslizante de Tamanho de Ícone em seu menu de engrenagem, para que você possa deixá-lo maior ou menor."
L["The interrupt flash now clears the instant a target dies, so the cast bar no longer looks squished by the death animation."] = "O flash de interrupção agora se limpa no instante em que um alvo morre, então a barra de lançamento não fica mais espremida pela animação de morte."
L["The spell picker now ends with a Missing Spells? shortcut that opens Blizzard's Cooldown Manager so you can add spells that are not listed."] = "O seletor de feitiços agora termina com um atalho Feitiços Faltando? que abre o Gerenciador de Recargas da Blizzard, para que você possa adicionar feitiços que não estão listados."
L["Themed Blizzard frames: Character Sheet, tooltips, menus, popups, Dragon Riding HUD."] = "Quadros temáticos da Blizzard: Ficha de Personagem, dicas de ferramenta, menus, pop-ups, HUD de Voo de Dragão."
L["This change requires a UI reload to take effect."] = "Esta alteração requer uma recarga da interface para ter efeito."
L["This element shows as soon as ONE condition matches, and a Hide lane then means show while that condition is false."] = "Este elemento aparece assim que UMA condição corresponde, e uma faixa de Ocultar significa mostrar enquanto essa condição for falsa."
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally ~150 for melee and ~300 for casters. Higher if you have high local ping."] = "Esta é a Janela de Fila de Feitiços, ela ajuda a garantir que você não possa enfileirar muitos feitiços de uma vez, o que faz o jogo parecer travado. As configurações recomendadas geralmente são ~150 para corpo a corpo e ~300 para conjuradores. Mais alto se você tiver ping local alto."
L["This option Show Duration (Inside Cog) Enabled"] = "Esta opção requer Mostrar Duração (Dentro da Engrenagem) Ativado"
L["This option is currently under maintenance"] = "Esta opção está atualmente em manutenção"
L["This option is disabled while a Center Text is selected."] = "Esta opção está desativada enquanto um Texto Central está selecionado."
L["This option requires %s to be enabled"] = "Esta opção requer que %s esteja ativado"
L["This option requires Set UI Scale to 0.5333 to be disabled"] = "Esta opção requer que Definir Escala da Interface para 0.5333 esteja desativado"
L["This option requires Show Tanks in Extra Group or a bound hotkey."] = "Esta opção requer Mostrar Tanques no Grupo Extra ou uma tecla de atalho vinculada."
L["This option requires a perpendicular Group Growth"] = "Esta opção requer um Crescimento de Grupo perpendicular"
L["This overwrites the chosen frame's current settings. Frame position, visibility, and enable state are not changed."] = "Isso substitui as configurações atuais do quadro escolhido. A posição, visibilidade e estado de ativação do quadro não são alterados."
L["This replaces %d existing value(s) for this setting across your specs. Do you want to continue?"] = "Isso substitui %d valor(es) existente(s) para esta configuração em todas as suas especializações. Deseja continuar?"
L["This replaces %d existing value(s) for this setting on this bar. Do you want to continue?"] = "Isso substitui %d valor(es) existente(s) para esta configuração nesta barra. Deseja continuar?"
L["This replaces 3 existing value(s) for this setting across your specs. Do you want to continue?"] = "Isso substitui 3 valor(es) existente(s) para esta configuração em todas as suas especializações. Deseja continuar?"
L["This setting requires a UI reload to take effect."] = "Esta configuração requer uma recarga da interface para ter efeito."
L["This will create a fully unique Buff Manager for this conditional group. Your current Buff Manager settings are copied as its starting point, and changes made to your default Buff Manager will no longer affect it."] = "Isso criará um Gerenciador de Buffs totalmente exclusivo para este grupo condicional. Suas configurações atuais do Gerenciador de Buffs são copiadas como ponto de partida, e alterações feitas no seu Gerenciador de Buffs padrão não afetarão mais este grupo."
L["This will create a fully unique Buff Manager for this override group. Your current Buff Manager settings are copied as its starting point, and changes made to your default Buff Manager will no longer affect these specs."] = "Isso criará um Gerenciador de Buffs totalmente exclusivo para este grupo de substituição. Suas configurações atuais do Gerenciador de Buffs são copiadas como ponto de partida, e alterações feitas no seu Gerenciador de Buffs padrão não afetarão mais essas especializações."
L["This will display ALL of your debuffs on enemy nameplates, rather than only the important ones."] = "Isso exibirá TODOS os seus debuffs nas placas de nome inimigas, em vez de apenas os importantes."
L["This will overwrite %1$s settings on the selected profiles with your current settings. Continue?"] = "Isso substituirá as configurações de %1$s nos perfis selecionados pelas suas configurações atuais. Continuar?"
L["This will reset all default bar spell assignments for the current spec to match Blizzard's CDM layout. Custom bars are not affected. Continue?"] = "Isso redefinirá todas as atribuições de feitiço das barras padrão da especialização atual para corresponder ao layout do CDM da Blizzard. Barras personalizadas não são afetadas. Continuar?"
L["This will reset all saved panel positions and reload your UI."] = "Isso redefinirá todas as posições de painel salvas e recarregará sua interface."
