L["When enabled, EUI relinquishes full control of friendly player nameplates to Blizzard."] = "Quando ativado, o EUI abre mão do controle total das placas de nome de jogadores amigos para a Blizzard."
L["When enabled, debuff icons keep Blizzard's colored border instead of using the custom border."] = "Quando ativado, os ícones de debuff mantêm a borda colorida da Blizzard em vez de usar a borda personalizada."
L["When enabled, nameplates stack vertically instead of overlapping."] = "Quando ativado, as placas de nome se empilham verticalmente em vez de se sobrepor."
L["When on, flask/food/weapon reminders still show (dimmed) when you have no matching item in your bags, as a prompt to restock.\nWhen off, they are hidden entirely if you don't carry the item."] = "Quando ativado, os lembretes de elixir/comida/arma ainda aparecem (esmaecidos) quando você não tem o item correspondente nas bolsas, como um aviso para reabastecer.\nQuando desativado, eles ficam totalmente ocultos se você não carrega o item."
L["When your spec has no class resource, automatically adds the class resource height to the power bar. Automatically disabled when Power Bar height is matched to another element."] = "Quando sua especialização não tem recurso de classe, adiciona automaticamente a altura do recurso de classe à barra de poder. Desativado automaticamente quando a altura da Barra de Poder está correspondida a outro elemento."
L["Which direction new icons extend from the frame's edge."] = "Em que direção novos ícones se estendem a partir da borda do quadro."
L["Which enemy buffs show on nameplates. Important shows the buffs Blizzard flags for enemy nameplates plus anything dispellable; Dispellable shows only buffs that can be dispelled, purged or soothed. With a Dispel Glow style set, every dispellable buff shown glows."] = "Quais buffs inimigos aparecem nas placas de nome. Importante mostra os buffs que a Blizzard marca para placas de nome inimigas, além de qualquer um dissipável; Dissipável mostra apenas buffs que podem ser dissipados, purgados ou acalmados. Com um estilo de Brilho de Dissipação definido, todo buff dissipável exibido brilha."
